module tb #(parameter integer MUT = 0);
    `include "qcluster_lat.svh"
    `include "q3h_cb16_tbdefs.svh"
    localparam integer NOPS = 4, TLD = 5, LN = 10, T_TILE = TLD + 3;
    localparam integer LAT_RS = Q3H_LAT_RS_FABRIC + T_TILE + 4 * LN;
    reg ck = 1'b0;
