    reg [513:0] rsi_hist [0:1023];
    initial begin
        if ($test$plusargs("FAR")) far = 1'b1;
        for (o = 0; o < NOPS; o = o + 1) t_go[o] = 90 + 48 * o;
        for (c = 0; c < 4; c = c + 1) begin bcw[c] = 516'd0; bseen[c] = 0; end
        rsi = 514'd0;
