    // rs_i stimulus: every cycle a distinct word (valid bit 512 set on 4 op words), recorded for the rs_o compare
    always @(negedge ck) begin
        rst_n <= (cyc >= 40);
        for (c = 0; c < 4; c = c + 1) bcw[c] <= 516'd0;
        for (o = 0; o < NOPS; o = o + 1)
            for (e = 0; e < 4; e = e + 1)
